	}
	m := newSearchModel(results, "q", 50, cfg, ss)

	// Navigate to page 2 — should NOT trigger fetch (data already loaded)
	updated, cmd := m.Update(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'n'}})
	m, ok := updated.(searchModel)
	if !ok {
